assert.ok(/\.detail-choice\s*\{[^}]*height:54px/.test(styles), 'track selectors must retain the compact LG target-size floor');
assert.ok(/function updateSummaryOverflow\(\)[\s\S]*scrollHeight > summary\.clientHeight[\s\S]*button\.disabled = !state\.summaryOverflowing/.test(scripts), 'the full-description control must only become focusable when text actually overflows');
assert.ok(/state\.zone === 'play'[\s\S]{0,520}direction === 'up' && options\.summaryOverflowing[\s\S]*state\.zone = 'summary'/.test(scripts), 'Up from every detail action must reach an overflowing description while preserving the fast Season-to-Play path');
assert.ok(/summaryOpen: summaryOpen[\s\S]*closeSummary: presentationView\.closeSummary[\s\S]*scrollSummary: presentationView\.scrollSummary/.test(detailFeatureControllerSource) && /if \(call\(values\.summaryOpen\)\)[\s\S]*code === 27 \|\| code === 461[\s\S]*call\(values\.closeSummary\)[\s\S]*call\(values\.scrollSummary/.test(detailControllerSource), 'the full-description dialog must support remote scrolling and Back');

console.log('TV shell compatibility checks passed');
